    /// Evaluates `raw_vaddr(<arg_sql>)` and returns the resulting cell (`None` == SQL NULL).
    fn eval_raw_vaddr(database: &Database, arg_sql: &str) -> Option<ColumnValue> {
        database
            .query(&format!("SELECT raw_vaddr({arg_sql}) AS result"))
            .expect("raw_vaddr query should always execute")
            .row_list[0]
            .get("result")
            .expect("result column")
            .clone()
    }

    #[test]
    fn test_raw_vaddr_hex_roundtrips_display() {
        for raw in [0u64, 0x80, 0xffffffff8e600000, u64::MAX] {
            let address: VirtualAddress = format!("vaddr(0x000000010fb6e000, 0x{raw:016x})")
                .parse()
                .unwrap();

            assert_eq!(
                raw_vaddr_hex(&format!("{address}")),
                Some(format!("{raw:016x}"))
            );
        }
    }

    #[test]
    fn test_raw_vaddr_sql_function_dispatches_value_types() {
        let database = Database::new().unwrap();

        assert_eq!(
            eval_raw_vaddr(&database, "'vaddr(0x000000010fb6e000, 0xffffffff8e600000)'"),
            Some(ColumnValue::String("ffffffff8e600000".to_string()))
        );

        for argument in ["NULL", "123", "-1", "1.5", "x'0011'", "'invalid'"] {
            assert_eq!(
                eval_raw_vaddr(&database, argument),
                None,
                "argument `{argument}` should yield NULL"
            );
        }
    }

    #[test]
    fn test_raw_vaddr_hex_returns_none_on_unparseable_text() {
        for value in [
            "",
            "invalid",
            "0xffffffff8e600000",
            "vaddr(0xffffffff8e600000)",
            "vaddr(0x1, 0xnothex)",
            "vaddr(0x1, 0xabc",
            "notvaddr(0x1, 0xabc)",
        ] {
            assert_eq!(raw_vaddr_hex(value), None, "`{value}` should not parse");
        }
    }

    #[test]
    fn test_raw_vaddr_hex_zero_pads() {
        let lower = raw_vaddr_hex("vaddr(0x0, 0x0000000000000080)").unwrap();
        let higher = raw_vaddr_hex("vaddr(0x0, 0x0000000000000100)").unwrap();

        assert_eq!(lower, "0000000000000080");
        assert_eq!(higher, "0000000000000100");
        assert!(lower < higher, "`{lower}` must sort before `{higher}`");
    }

    /// Evaluates `expect(<args_sql>)`: `Ok(cell)` on success, `Err` when it raises.
    fn expect_query(database: &Database, args_sql: &str) -> Result<Option<ColumnValue>> {
        database
            .query(&format!("SELECT expect({args_sql}) AS result"))
            .map(|data| {
                data.row_list[0]
                    .get("result")
                    .expect("result column")
                    .clone()
            })
    }

    #[test]
    fn test_expect_passes_present_values_through_unchanged() {
        let database = Database::new().unwrap();

        assert_eq!(
            expect_query(&database, "'hello', 'boom'").unwrap(),
            Some(ColumnValue::String("hello".to_string()))
        );

        assert_eq!(
            expect_query(&database, "42, 'boom'").unwrap(),
            Some(ColumnValue::SignedInteger(42))
        );

        assert_eq!(
            expect_query(&database, "1.5, 'boom'").unwrap(),
            Some(ColumnValue::Double(1.5))
        );
    }

    #[test]
    fn test_expect_raises_the_message_on_null() {
        let database = Database::new().unwrap();

        match expect_query(&database, "NULL, 'could not resolve _stext'").unwrap_err() {
            Error::TablePlugin(message) => {
                assert!(
                    message.contains("could not resolve _stext"),
                    "got: {message}"
                )
            }
            other => panic!("expected a TablePlugin error, got {other:?}"),
        }
    }

    #[test]
    fn test_expect_requires_two_arguments() {
        let database = Database::new().unwrap();

        assert!(matches!(
            expect_query(&database, "1").unwrap_err(),
            Error::InvalidSqlStatement(_)
        ));

        assert!(matches!(
            expect_query(&database, "1, 'a', 'b'").unwrap_err(),
            Error::InvalidSqlStatement(_)
        ));
    }
}

"""Configuration models and environment handling."""

import os
from pathlib import Path

from pydantic import BaseModel, Field, field_validator


class S3Config(BaseModel):
    """S3/Spaces configuration from environment variables."""

    bucket: str
    endpoint: str
    access_key_id: str
    secret_access_key: str

    @classmethod
    def from_env(cls) -> "S3Config":
        """Load S3 configuration from environment variables."""
        bucket = os.environ.get("MQUIRE_TEST_S3_BUCKET")
        endpoint = os.environ.get("MQUIRE_TEST_S3_ENDPOINT")
        access_key_id = os.environ.get("MQUIRE_TEST_AWS_ACCESS_KEY_ID")
        secret_access_key = os.environ.get("MQUIRE_TEST_AWS_SECRET_ACCESS_KEY")

        missing = []
        if not bucket:
            missing.append("MQUIRE_TEST_S3_BUCKET")
        if not endpoint:
            missing.append("MQUIRE_TEST_S3_ENDPOINT")
        if not access_key_id:
            missing.append("MQUIRE_TEST_AWS_ACCESS_KEY_ID")
        if not secret_access_key:
            missing.append("MQUIRE_TEST_AWS_SECRET_ACCESS_KEY")

        if missing:
            raise ValueError(f"Missing required environment variables: {', '.join(missing)}")

        # Type narrowing: all values are guaranteed to be set after the check above
        assert bucket is not None
        assert endpoint is not None
        assert access_key_id is not None
        assert secret_access_key is not None

        return cls(
            bucket=bucket,
            endpoint=endpoint,
            access_key_id=access_key_id,
            secret_access_key=secret_access_key,
        )


class ManifestConfig(BaseModel):
    """Configuration loaded from manifest.json."""

    mquire_path: str = Field(description="Path to mquire binary (relative to manifest)")
    tests: dict[str, str] = Field(
        description="Mapping of snapshot filename to SQL test directory path"
    )
    architecture: str = Field(default="intel", description="CPU architecture")
    operating_system: str = Field(default="linux", description="Operating system")
    local_snapshots_path: str = Field(
        default="../snapshots", description="Local path for downloaded snapshots"
    )
    timeout_seconds: int = Field(default=300, description="Timeout per query in seconds")

    # Set after loading, not from JSON
    _manifest_dir: Path | None = None

    @field_validator("tests")
    @classmethod
    def validate_tests(cls, v: dict[str, str]) -> dict[str, str]:
        """Validate tests mapping."""
        if not v:
            raise ValueError("tests mapping cannot be empty")
        return v

    def set_manifest_dir(self, manifest_path: Path) -> None:
        """Set the manifest directory for path resolution."""
        self._manifest_dir = manifest_path.parent.resolve()

    def resolve_path(self, path: str) -> Path:
        """Resolve a path relative to the manifest directory."""
        if self._manifest_dir is None:
            raise ValueError("Manifest directory not set. Call set_manifest_dir() first.")
        p = Path(path)
        if p.is_absolute():
            return p
        return (self._manifest_dir / p).resolve()

    def get_mquire_path(self) -> Path:
        """Get resolved mquire binary path."""
        return self.resolve_path(self.mquire_path)

    def get_snapshots_path(self) -> Path:
        """Get resolved local snapshots path: <local_snapshots_path>/<os>/<arch>/."""
        base = self.resolve_path(self.local_snapshots_path)
        return base / self.operating_system.lower() / self.architecture.lower()

    def get_snapshot_names(self) -> list[str]:
        """Get list of snapshot filenames."""
        return list(self.tests.keys())

    def get_sql_path_for_snapshot(self, snapshot_name: str) -> Path:
        """Get the SQL query path for a specific snapshot."""
        if snapshot_name not in self.tests:
            raise ValueError(f"Snapshot '{snapshot_name}' not found in tests mapping")
        return self.resolve_path(self.tests[snapshot_name])

    @classmethod
    def load(cls, manifest_path: Path) -> "ManifestConfig":
        """Load configuration from a manifest file."""
        import json

        with manifest_path.open() as f:
            data = json.load(f)

        config = cls.model_validate(data)
        config.set_manifest_dir(manifest_path)
        return config

"""JSON output comparison utilities."""

import json
from dataclasses import dataclass
from typing import Any


@dataclass
class ComparisonResult:
    """Result of comparing actual vs expected JSON output."""

    passed: bool
    message: str
    expected_row_count: int
    actual_row_count: int
    diff_details: str | None = None


def _extract_row_list(data: Any) -> tuple[list[Any] | None, list[str] | None, str | None]:
    """Extract row_list and column_order from mquire JSON output format.

    mquire outputs: {"column_order": [...], "row_list": [...]}

    Args:
        data: Parsed JSON data

    Returns:
        Tuple of (row_list, column_order, error_message)
    """
    if not isinstance(data, dict):
        return None, None, f"Expected dict, got {type(data).__name__}"
    if "row_list" not in data:
        return None, None, "JSON object missing 'row_list' key"
    if "column_order" not in data:
        return None, None, "JSON object missing 'column_order' key"

    row_list = data["row_list"]
    column_order = data["column_order"]

    if not isinstance(row_list, list):
        return None, None, f"row_list is not a list, got {type(row_list).__name__}"
    if not isinstance(column_order, list):
        return None, None, f"column_order is not a list, got {type(column_order).__name__}"

    return row_list, column_order, None


def compare_json_output(
    actual: str,
    expected: str,
) -> ComparisonResult:
    """Compare actual mquire JSON output against expected output.

    Handles mquire's JSON format: {"column_order": [...], "row_list": [...]}
    Performs exact comparison: row count and content must match.

    Args:
        actual: Actual JSON output from mquire
        expected: Expected JSON content

    Returns:
        ComparisonResult with pass/fail status and details
    """
    try:
        actual_data = json.loads(actual)
    except json.JSONDecodeError as e:
        return ComparisonResult(
            passed=False,
            message=f"Failed to parse actual output as JSON: {e}",
            expected_row_count=-1,
            actual_row_count=-1,
        )

    try:
        expected_data = json.loads(expected)
    except json.JSONDecodeError as e:
        return ComparisonResult(
            passed=False,
            message=f"Failed to parse expected output as JSON: {e}",
            expected_row_count=-1,
            actual_row_count=-1,
        )

    actual_rows, actual_cols, actual_err = _extract_row_list(actual_data)
    if actual_err:
        return ComparisonResult(
            passed=False,
            message=f"Actual output: {actual_err}",
            expected_row_count=-1,
            actual_row_count=-1,
        )

    expected_rows, expected_cols, expected_err = _extract_row_list(expected_data)
    if expected_err:
        return ComparisonResult(
            passed=False,
            message=f"Expected output: {expected_err}",
            expected_row_count=-1,
            actual_row_count=-1,
        )

    # Type narrowing: if no error, values are not None
    assert actual_rows is not None
    assert expected_rows is not None
    assert actual_cols is not None
    assert expected_cols is not None

    if actual_cols != expected_cols:
        return ComparisonResult(
            passed=False,
            message=f"Column order mismatch: expected {expected_cols}, got {actual_cols}",
            expected_row_count=len(expected_rows),
            actual_row_count=len(actual_rows),
        )

    expected_count = len(expected_rows)
    actual_count = len(actual_rows)

    if expected_count != actual_count:
        return ComparisonResult(
            passed=False,
            message=f"Row count mismatch: expected {expected_count}, got {actual_count}",
            expected_row_count=expected_count,
            actual_row_count=actual_count,
        )

    if actual_rows != expected_rows:
        diff = _find_differences(actual_rows, expected_rows)
        return ComparisonResult(
            passed=False,
            message="Content mismatch",
            expected_row_count=expected_count,
            actual_row_count=actual_count,
            diff_details=diff,
        )

    return ComparisonResult(
        passed=True,
        message="OK",
        expected_row_count=expected_count,
        actual_row_count=actual_count,
    )


def _find_differences(actual: list[Any], expected: list[Any]) -> str:
    """Find and describe differences between actual and expected data.

    Args:
        actual: Actual data list
        expected: Expected data list

    Returns:
        Human-readable description of differences
    """
    differences = []
    max_diffs = 5

    for i, (act_row, exp_row) in enumerate(zip(actual, expected, strict=True)):
        if act_row != exp_row:
            if isinstance(act_row, dict) and isinstance(exp_row, dict):
                row_diffs = _compare_dicts(act_row, exp_row)
                differences.append(f"Row {i}: {row_diffs}")
            else:
                differences.append(f"Row {i}: expected {exp_row!r}, got {act_row!r}")

            if len(differences) >= max_diffs:
                remaining = sum(
                    1 for a, e in zip(actual[i + 1 :], expected[i + 1 :], strict=True) if a != e
                )
                if remaining > 0:
                    differences.append(f"... and {remaining} more differences")
                break

    return "\n".join(differences)


def _compare_dicts(actual: dict[str, Any], expected: dict[str, Any]) -> str:
    """Compare two dictionaries and describe differences.

    Args:
        actual: Actual dictionary
        expected: Expected dictionary

    Returns:
        Description of field-level differences
    """
    diffs = []

    all_keys = set(actual.keys()) | set(expected.keys())
    for key in sorted(all_keys):
        if key not in actual:
            diffs.append(f"missing field '{key}'")
        elif key not in expected:
            diffs.append(f"extra field '{key}'")
        elif actual[key] != expected[key]:
            diffs.append(f"field '{key}': expected {expected[key]!r}, got {actual[key]!r}")

    return "; ".join(diffs) if diffs else "unknown difference"

